*********************
*** construct multimarket measures
***********************
clear
use "multimarketmatrix.dta"

** maximum multimarket 
* max i in loops = maximum number of industries
egen max_mm=rowmax(mm_rank*)
local i=2
while `i'<=70 {
quietly{

egen max_rank`i'=max(mm_rank`i'), by(msa_number fiscal_year sic2digit)

local i=`i'+1
}
}

gen max_mm2=0
local i=2
while `i'<=70 {
quietly{

replace max_mm2=max_rank`i' if rank==`i'

local i=`i'+1
}
}

egen multimarket_max=rowmax(max_mm max_mm2)
drop max_rank*

foreach var in varlist lnfees  lnmultimarket_mean   lnta busseg cata de leader firstyear gc loss  mw roi   big4 yearend  {
drop if `var'==.
}

di _N
save "regressiondata.dta",replace

local i=`i'+1
}
